package org.example.socialmediabackend.controller;
import org.example.socialmediabackend.model.*;import org.example.socialmediabackend.repository.*;import org.example.socialmediabackend.service.ApiMapper;import org.springframework.http.*;import org.springframework.security.core.Authentication;import org.springframework.web.bind.annotation.*;import java.util.*;
@RestController @RequestMapping("/comments") public class CommentController {
 private final CommentRepository comments;private final PostRepository posts;private final UserRepository users;
 public CommentController(CommentRepository c,PostRepository p,UserRepository u){comments=c;posts=p;users=u;}
 @GetMapping("/post/{postId}") public List<Map<String,Object>> byPost(@PathVariable Long postId){if(!posts.existsById(postId))throw new org.example.socialmediabackend.exception.ResourceNotFoundException("Post not found");return comments.findByPostIdOrderByCreatedAtAsc(postId).stream().map(ApiMapper::comment).toList();}
 @PostMapping public ResponseEntity<?> create(@RequestBody Map<String,Object> b,Authentication auth){Long postId=asLong(b.get("postId"));String message=Objects.toString(b.get("message"),"").trim();if(postId==null||message.isBlank()||message.length()>1000)return ResponseEntity.badRequest().body(Map.of("message","postId and a comment of 1-1000 characters are required"));Post p=posts.findById(postId).orElseThrow(()->new org.example.socialmediabackend.exception.ResourceNotFoundException("Post not found"));User u=users.findByEmailIgnoreCase(auth.getName()).orElseThrow();Comment c=new Comment();c.setPost(p);c.setUser(u);c.setMessage(message);return ResponseEntity.status(201).body(ApiMapper.comment(comments.save(c)));}
 @DeleteMapping("/{id}") public ResponseEntity<?> delete(@PathVariable Long id,Authentication auth){Comment c=comments.findById(id).orElseThrow(()->new org.example.socialmediabackend.exception.ResourceNotFoundException("Comment not found"));User actor=users.findByEmailIgnoreCase(auth.getName()).orElseThrow();if(!c.getUser().getId().equals(actor.getId()))return ResponseEntity.status(403).body(Map.of("message","You can only delete your own comments"));comments.delete(c);return ResponseEntity.noContent().build();}
 private Long asLong(Object o){try{return Long.valueOf(o.toString());}catch(Exception e){return null;}}
}
